def transform(grid):
    # Tile the non-background pattern in the boxed area across adjacent regions,
    # preserving the separator lines. Infer the pattern tile from the first region.
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    # separator color appears as full horizontal/vertical lines
    sep = None
    for r,row in enumerate(grid):
        if len(set(row)) == 1:
            sep = row[0]
            break
    if sep is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                sep=grid[0][c]; break
    # Locate full separator row/column; tile contents of upper-left cell region.
    sr = next((r for r,row in enumerate(grid) if all(v==sep for v in row)), None)
    sc = next((c for c in range(w) if all(grid[r][c]==sep for r in range(h))), None)
    out=[row[:] for row in grid]
    if sr is not None and sc is not None:
        # reflect/periodically repeat the pattern found in top-left region into other quadrants
        for r in range(h):
            for c in range(w):
                if r==sr or c==sc: continue
                out[r][c]=grid[r % sr][c % sc]
    elif sc is not None:
        for r in range(h):
            for c in range(w):
                if c!=sc: out[r][c]=grid[r][c % sc]
    elif sr is not None:
        for r in range(h):
            for c in range(w):
                if r!=sr: out[r][c]=grid[r % sr][c]
    return out
